def fitwin(L,LO,HI):
    X=np.concatenate([D[L][k] for k in range(LO,HI)]); Y=np.tile(y,HI-LO)
    X=torch.tensor(X); mu=X.mean(0); sd=X.std(0)+1e-6; Xn=(X-mu)/sd; yt=torch.tensor(Y,dtype=torch.float32)
    w=torch.zeros(X.shape[1],requires_grad=True); b=torch.zeros(1,requires_grad=True)
    opt=torch.optim.Adam([w,b],lr=0.05); pw=torch.tensor(4.0)
